import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { ToastProps } from "./toast.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Toast";

// Generate child element class names for the component, should match available style slots
export const ToastClasses = {
  root: "exp-textura_toast",
  icon: "exp-textura_toast_icon",
  message: "exp-textura_toast_message",
  slideIn: "exp-textura_toast_slide_in",
  topStart: "exp-textura_toast_position_ts",
  topCenter: "exp-textura_toast_position_tc",
  topEnd: "exp-textura_toast_position_te",
  bottomStart: "exp-textura_toast_position_bs",
  bottomCenter: "exp-textura_toast_position_bc",
  bottomEnd: "exp-textura_toast_position_be",
  clickToDismiss: "exp-textura_toast_click_to_dismiss",
  closeIconButton: "exp-textura_toast_close_icon_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      backgroundColor: theme.toast.critical.background,
      color: theme.toast.critical.content,
    },
  },
  success: {
    root: {
      backgroundColor: theme.toast.success.background,
      color: theme.toast.success.content,
    },
  },
});

const generateStyles = (props: ToastProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ToastProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    borderRadius: theme.toRem(theme.border.radius.sm),
    ...theme.typography.body.mdEmphasis,
    padding: theme.toRem(theme.spacing[8]),
    minWidth: theme.toRem(400),
    transition: "all 250ms ease",
    opacity: 0,
    position: "fixed",
    display: "flex",
    alignItems: "center",
    backgroundColor: theme.toast.default.background,
    color: theme.toast.default.content,

    '&[data-textura-scoped="true"]': {
      position: "absolute",
    },

    "&:hover": {
      ...styleSlots?.hover,
    },

    "&:focus-visible": {
      ...styleSlots?.focus,
    },

    [`.${ToastClasses.icon}`]: {
      display: "flex",
      alignItems: "center",
      ...styleSlots?.icon,
    },

    [`.${ToastClasses.message}`]: {
      display: "flex",
      alignItems: "center",
      flexGrow: 1,
      gap: theme.toRem(theme.spacing[8]),
      paddingInlineStart: theme.toRem(theme.spacing[8]),
      ...styleSlots?.message,
    },

    // transforms to create a slide-in effect when toast is set to show
    [`&.${ToastClasses.slideIn}`]: {
      opacity: 1,

      [`&.${ToastClasses.bottomStart}, &.${ToastClasses.bottomEnd}`]: {
        transform: "translateY(0)",
        bottom: theme.getSpacing(1),
      },

      [`&.${ToastClasses.bottomCenter}`]: {
        transform: "translate(-50%, 0)",
        bottom: theme.getSpacing(1),
      },

      [`&.${ToastClasses.topStart}, &.${ToastClasses.topEnd}`]: {
        transform: "translateY(0)",
        top: theme.getSpacing(1),
      },

      [`&.${ToastClasses.topCenter}`]: {
        transform: "translate(-50%, 0)",
        top: theme.getSpacing(1),
      },

      ...styleSlots?.slideIn,
    },

    [`&.${ToastClasses.bottomStart}`]: {
      insetInlineStart: theme.getSpacing(1),
      bottom: 1,
      transform: "translateY(100%)",
      ...styleSlots?.bottomStart,
    },

    [`&.${ToastClasses.bottomCenter}`]: {
      left: "50%",
      bottom: theme.toRem(1),
      transform: "translate(-50%, 100%)",
      ...styleSlots?.bottomCenter,
    },

    [`&.${ToastClasses.bottomEnd}`]: {
      insetInlineEnd: theme.getSpacing(1),
      bottom: 1,
      transform: "translateY(100%)",
      ...styleSlots?.bottomEnd,
    },

    [`&.${ToastClasses.topStart}`]: {
      insetInlineStart: theme.getSpacing(1),
      top: 1,
      transform: "translateY(-100%)",
      ...styleSlots?.topStart,
    },

    [`&.${ToastClasses.topCenter}`]: {
      left: "50%",
      top: theme.toRem(1),
      transform: "translate(-50%, -100%)",
      ...styleSlots?.topCenter,
    },

    [`&.${ToastClasses.topEnd}`]: {
      insetInlineEnd: theme.getSpacing(1),
      top: 1,
      transform: "translateY(-100%)",
      ...styleSlots?.topEnd,
    },

    [`&.${ToastClasses.clickToDismiss}`]: {
      cursor: "pointer",
      ...styleSlots?.clickToDismiss,
    },

    [`.${ToastClasses.closeIconButton}`]: {
      ...styleSlots?.closeIconButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledToast = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ToastProps>((props) => generateStyles(props));
